*** Begin Patch
*** Update File: source/pdf/pdf-cmap-parse.c
@@
 		if (buf->len / 2)
 		{
 			size_t i;
-			size_t len = fz_minz(buf->len / 2, nelem(dst));
+			size_t len = fz_minz(buf->len / 2, nelem(dst));
 			for (i = 0; i < len; i++)
